/**
 * The real beta catalogue: products from the Christmas 2026 top-toy lists, with prices
 * and links checked through search results on 29 Oct 2026 (see docs/research/).
 * Prices change: affiliate feeds will keep them current (docs/affiliates/).
 *
 * The data lives in beta-catalogue.json, generated by `npm run catalogue`.
 */
import type { Category, Product } from '@/domain/types';

import beta from './beta-catalogue.json';

/** What each page looks like in Kid Mode: one simple word and a picture. */
const KID_TILES: Record<string, { kidLabel: string; icon: string }> = {
  bricks: { kidLabel: 'Bricks', icon: '🧱' },
  pretend: { kidLabel: 'Pretend', icon: '🏠' },
  dolls: { kidLabel: 'Dolls', icon: '🪆' },
  interactive: { kidLabel: 'Pets', icon: '🤖' },
  soft: { kidLabel: 'Teddies', icon: '🧸' },
  music: { kidLabel: 'Music', icon: '🎵' },
  crafts: { kidLabel: 'Art', icon: '🎨' },
  outdoor: { kidLabel: 'Outside', icon: '🚲' },
  games: { kidLabel: 'Games', icon: '🎲' },
  little: { kidLabel: 'Baby', icon: '👶' },
};

export const categories: Category[] = beta.pages.map((page) => ({
  key: page.key,
  title: page.title,
  familyCode: page.familyCode,
  ...(KID_TILES[page.key] ?? { kidLabel: page.title, icon: '🎁' }),
}));

/** The page for products a family added themselves (pasted links). Only shown once there are some. */
export const yourFinds: Category = { key: 'yours', title: 'Your Finds', kidLabel: 'Yours', icon: '⭐', familyCode: 900 };

export const products: Product[] = beta.products.map((p) => ({
  // Stable across catalogue updates, so a child's circles survive a price change.
  id: `c${p.catalogueNo.replace('/', '-')}`,
  catalogueNo: p.catalogueNo,
  title: p.title,
  categoryKey: p.page,
  priceMinor: p.priceMinor,
  currency: p.currency,
  retailer: p.retailer,
  url: p.url,
  emoji: p.emoji,
}));

export const productsById: Record<string, Product> = Object.fromEntries(products.map((p) => [p.id, p]));

export const productsIn = (categoryKey: string) => products.filter((p) => p.categoryKey === categoryKey);

/** When prices were last checked, for the "prices as of" note. */
export const pricesCheckedOn = beta.asOf;
